quests[88805] = { id = 88805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarred Path Through Time", description = "Old enemies return and battle scars open once more.\n\nDefeat these foes and return with tales of glory.", completion = "What news from the war front?", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88808] = { id = 88808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarred Journey Through Time", description = "Azeroth calls out in need, champion. She bleeds still from wounds of war. Go forth among Zandalar and Kul Tiras to reveal those who would prolong her suffering.\n\nVanquish foes in her name and defend Azeroth.", completion = "I knew I could trust in you to complete such a feat.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
