quests[88902] = { id = 88902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Restless Souls" }
quests[88903] = { id = 88903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faceless Mask of Vengeance", description = "Blood begets blood, and the weight of the fallen lingers in the air like a whispered curse. Those who stand witness to your wrath feel it creeping into their bones, driving them to strike harder, desperation masquerading as courage. Vengeance does not end violence. It only feeds the storm.", progress = "Place the Faceless Mask of Vengeance on the altar.", completion = "Be prepared to face the wrath of your enemies should you don this mask.", objectives = "Return the Faceless Mask of Vengeance to the altar within a Horrific Vision.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88904] = { id = 88904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: It Could Be Anything" }
quests[88916] = { id = 88916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Radiant Incursion: Sureki's End", description = "Credible intel has revealed the Sureki are regrouping for another assault. Now we take the fight to them!\n\nThe Flame's Radiance have rallied at Faerin's Advance, and prepare to strike at the Sureki forces amassing in northern Azj-Kahet.\n\nBe warned, soldier. The Sureki in \"Arathi's End\" are greater in number and power. \n\nShould you require aid, our Sacredites in the field should be equipped with potions to assist you.", progress = "We must not let them gather strength. Now is the time to strike!", completion = "Many Lamplighters and soldiers have been lost in the graveyard they call \"Arathi's End\".\n\nOn behalf of those lost in the dark, and those here on the front, I thank you.", objectives = "Assist the Flame's Radiance and disrupt the Sureki forces at Arathi's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88919] = { id = 88919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Darkway", description = "Ulen's imposter may have escaped, but I suspect I know what the cult has been doing. \n\nThe Twilight's Blade must be redirecting Suramar's mana flow. Without it being sent to the correct places, our awareness dulls, our golems wilt, and our entire society risks a mana withdrawal.\n\nThere is only one place they would be able to exert control over our ley lines like this, and that would be the Arcway. \n\nGo. Find them and crush them. \n\nWe will meet in Silvermoon when you are done.", sourceObjective = "Slay Twilight Imposter Gulkat in the Darkway Delve.", completion = "Well done, champion. \n\nOur golems are coming back online, our soldiers are able to conjure and power their weapons again, and we are mobilizing for war.", sourceObjectiveStatus = "unverified-source-field" }
quests[88920] = { id = 88920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kaldorei", description = "We must retake the Darkwell and defeat L'ura before the world is torn asunder.\n\nWe will need an army. No. Many armies.\n\nWe need to reach out to the other elves. We should start with the kaldorei at Bel'ameth. Oculeth can teleport a small envoy there and we can present our request.\n\nStill... there has been much blood spilt among the elves. Vendettas that go far and strike deep. Hold on to hope, {name}. It is all we have left.", sourceObjective = "Listen to Arator's plan and then use Telemancer Oculeth's Portal to Bel'ameth.", progress = "Are you ready to depart, Champion?", completion = "This is quite the ensemble you've brought to my lands, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[88922] = { id = 88922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quel'dorei", description = "{name}, while the kaldorei are mustering, I could use your help as a witness as I ask another group for aid.\n\nWe will need the quel'dorei for what is to come, no matter how much some of the sin'dorei will protest. \n\nOculeth has agreed to open a portal for the two of us to reach my aunt, Vereesa Windrunner, where she awaits us in Eversong.\n\nThe sin'dorei will not come with me. Will you?", sourceObjective = "Take Oculeth's portal to Eversong Woods.", completion = "{name}, surely you remember my aunt, Vereesa Windrunner. You were with us at the ruins of Dalaran when her visions of the Void assaulting the Sunwell first manifested.\n\nShe and her Silver Covenant, what remains of the quel'dorei as they once were, will prove invaluable in the fight to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[88923] = { id = 88923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of the Stars", description = "You have traveled far to ask my people to march to yet another war.\n\nMaiev's fervor is blunt but not misplaced. While Silvermoon is under threat, let us not forget how many of my people burned when the sin'dorei failed to aid us at Teldrassil.\n\nHowever, Bel'ameth stands tall thanks to their aid. Let each present their reasoning and I shall then make my decision.", sourceObjective = "Have each envoy present their case to Shandris Feathermoon.", progress = "Have you more to add?", completion = "Very well. The Void represents a threat to this world we cannot ignore.\n\n<Shandris sighs.>\n\nI grow tired of yet another threat at the Sunwell that cannot be ignored.", sourceObjectiveStatus = "unverified-source-field" }
quests[88925] = { id = 88925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken the Ancient of War", description = "If we are to muster for war, then there is an ancient we must bring with us or they will never forgive us.\n\nThey are a mentor to myself and nearly every sentinel who serves the kaldorei. They are skilled in war, tactics, and rallying our greatest forces.\n\nAnd they fell asleep again. If history is any lesson, they will only awaken with the aid of someone who has known war.\n\nWill you seek out their grove keeper to learn how to awaken them?", sourceObjective = "Awaken the Ancient of War in Bel'ameth.", completion = "Well done, {name}. The forest marches to war.", sourceObjectiveStatus = "unverified-source-field" }
quests[88926] = { id = 88926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Belanaar", description = "This has been most productive. I suspected the kaldorei might be our the most difficult to convince, but Shandris has turned a new leaf of leadership for her people.\n\nLet this be the first of many successful partnerships between our people.\n\nNow swiftly, {name}. Let us return home and prepare our defense.", sourceObjective = "Return to the docks in Bel'ameth with Lor'themar and Shandris.", sourceObjectiveStatus = "unverified-source-field" }
quests[88927] = { id = 88927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken the Ancient Protector", description = "The enemy we face is a vast host with many capabilities. We will need to match their strength and versatility on the battlefield.\n\nTo that end, I ask that you seek out Elder Verdantbark--an ancient protector who has long kept our people safe in times of war.\n\nThey are stubborn and may require you to entice them in some fashion, but their grove keeper will know best how to do so.", sourceObjective = "Awaken the Ancient Protector in Bel'ameth.", completion = "Good. An ancient protector is capable of striking foes from afar with their boulders, be they on the ground or flying in the air.", sourceObjectiveStatus = "unverified-source-field" }
quests[88928] = { id = 88928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shal'dorei", description = "Champion, your timing is fortuitous. I sent the call for the armies of Suramar to muster, but they have not arrived yet.\n\nMy seneschal should have alerted me if anything went wrong, but I have heard nothing.\n\nI plan to go to Suramar to investigate what is amiss. Would you join me? I may have need of your skills.", sourceObjective = "Use Oculeth's portal to travel to Suramar.", completion = "I have no idea what the First Arcanist is referring to. We have been at peace for some time now.", sourceObjectiveStatus = "unverified-source-field" }
quests[88929] = { id = 88929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Illusion!", description = "The mana of Suramar is carefully cultivated, regulated, and controlled. It does not just randomly \"stop.\"\n\nSomeone or something must be interfering with it.\n\nAs you investigate the mana drain, I want you to occasionally dispel illusions in the area. Focus on those gathered here. I suspect not everyone is what they appear to be.", sourceObjective = "Dispel illusions in the Botanist's Garden that may be concealing sabotage or saboteurs.", progress = "How many of my people have been taken by this evil?", completion = "There were far more cultists than I would have expected. How long have they been infiltrating our society?", sourceObjectiveStatus = "unverified-source-field" }
quests[88930] = { id = 88930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drained Mana", description = "I have received no word from High Arcanist Thalyssra for days!\n\nWe have had many mana problems lately, so there is a chance her message spells were simply not able to be received.", sourceObjective = "Investigate the Mana Drain at the Botanist's Terrace in Suramar.", progress = "Have you found anything?", completion = "Ulen was an infiltrator? The amount of damage they could have done is terrifying to imagine.", sourceObjectiveStatus = "unverified-source-field" }
quests[88931] = { id = 88931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of Shadow" }
quests[88932] = { id = 88932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With the Shal'dorei", description = "Our reinforcements will be arriving shortly. Some will stay behind to defend Suramar. The rest will join us in Silvermoon.\n\nThank you for joining me in this journey, {name}. Hold on to the memory of this place in the battles to come. It will shield you from any doubt the void plants within you.\n\nAccompany me back to Silvermoon. We have many allies to find yet if we are to prevail against this force.", sourceObjective = "Meet First Arcanist Thalyssra in the Sanctum of Light in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[88937] = { id = 88937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken the Ancient of Lore", description = "While our forces gather, I would like you to have the honor of awakening our ancients.\n\nThere is a particular ancient of lore we will need awakened.\n\nThey are a master of magic, a teacher of our druids, and a force that has walked alongside us across many battlefields.\n\nFind their grove keeper to learn what is needed to wake the ancient.", sourceObjective = "Awaken an Ancient of Lore in Bel'ameth.", progress = "What stories does the ancient of lore have to tell, I wonder?", completion = "With the ancients by our side, we will be unstoppable.", sourceObjectiveStatus = "unverified-source-field" }
quests[88938] = { id = 88938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbols of the Past", description = "Arator's warning is poignant. There will be no small amount of grief or even threats when we return to Silvermoon. \n\nI suspect Aethas and his Sunreavers will bar our passage if we enter without preparations.\n\nTo that end, I have saved some precious remnants of our shared history from before the demise of Dalaran. Would you please gather them for me, {name}?", sourceObjective = "Gather the Relics of High King Anasterian Sunstrider.", progress = "We were not able to preserve much from Dalaran before its fall. But every object recovered carries with it history, meaning, and lessons--lessons that any citizen of Quel'Thalas should understand on sight.", completion = "The artifacts of the last High King of Quel'Thalas. He was someone all quel'dorei and sin'dorei respected. \n\nI intend to return these artifacts to their rightful home.", sourceObjectiveStatus = "unverified-source-field" }
quests[88939] = { id = 88939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest for the Restless", description = "Before we are able to make amends with the living, we must lay the dead to rest.\n\nYears ago, I purged Dalaran of all elves allied with the Horde. I blamed them for the actions of the warchief at the time that resulted in the death of my husband.\n\nNow, years later, those ghosts still haunt me. Will you put them to rest and gather their remains? I'll perform some small atonement by bringing these remains to Silvermoon. They deserve to be returned home.", sourceObjective = "Gather 10 Remains of the Fallen from the Purged of Dalaran.", progress = "I have allowed them to torment my people for too long. I bear that guilt as well.", completion = "Thank you, {name}. \n\nIt is time for me to bring these ghosts home.", sourceObjectiveStatus = "unverified-source-field" }
quests[88941] = { id = 88941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Quel'Thalas", description = "It is time for us to return to Silvermoon. I have no doubt we will be greeted as traitors and murderers.\n\nI do not care how we are seen. I care that Quel'Thalas survives.\n\nWill you join us, {name}? \n\nFrom what Arator has said, you have earned more than a measure of respect from Silvermoon. I would be honored if you would assist us in entering the city without incident.", sourceObjective = "Confront the Sunreavers with Vereesa Windrunner at the gates of Silvermoon.", completion = "Thank you, {name}.\n\nNow let's begin planning this city's defense before it is too late. Again.", sourceObjectiveStatus = "unverified-source-field" }
quests[88942] = { id = 88942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elves are Going to War", description = "We have learned much about the forces we will be facing in the battle to come.\n\nSuramar remembers the debt we owe the sin'dorei for their aid in our time of need. Now that our forces are assembled and our golems prepared, we are ready to defend this city as if it were our own.\n\nCome, {name}. Let us return to Lor'themar. It is time to discuss battle strategy.", sourceObjective = "Return to the Sanctum of Light in Silvermoon City.", completion = "Cultists? Xal'atath seems intent on undermining us at every turn. \n\nWe must be grateful she continues to underestimate your skills.\n\nWith the Nightborne ready, that means our forces are gathered. We will position ourselves and strategize how best to deploy our forces. \n\nThank you, champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[88945] = { id = 88945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Radiant Incursion: Rak-Zakaz", description = "The nerubian allies you and Lady Faerin made in Azj-Kahet have proven resourceful... for now.\n\nAccording to their intel, Sureki sympathizers have begun to rally at Rak-Zakaz and aid their fallen queen's loyalists in their renewed assaults.\n\nRegroup with our forces at Faerin's Advance and cut off their reinforcements!", progress = "By disrupting operations at Rak-Zakaz, we cut off their reinforcements and discourage any sympathizers to their cause.", completion = "We're lucky to have you down here. \n\nNot so long ago, we Arathi dared not delve this far into Azj-Kahet. Yet, here we are.\n\nYour actions in Rak-Zakaz should buy us a reprieve, and hopefully delay their next assault on the Aegis Wall.", objectives = "Assist the Flame's Radiance and disrupt the Sureki forces at Rak-Zakaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88947] = { id = 88947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undermined Delves", description = "There's more tae do in delves, {name}! \n\nMeet me in Dornogal. There's loads to discuss!", completion = "Good tae see ye! We've got plenty tae discuss.", objectives = "Meet Brann Bronzebeard within Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
