quests[88971] = { id = 88971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - 11.2 The War Within - Raid Finder - Nth" }
quests[88974] = { id = 88974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eco-Stability", description = "Speakin' o' eggs, I checked an' Ember has laid her clutch. It's almost time ta hatch some babies!\n\nMeet me back at tha nest an' we can welcome our first snakelets ta K'aresh.", completion = "The Oasis has surpassed my expectations, {name}, and I had very high expectations indeed. Your work has been invaluable.\n\nI never suspected when I met you in the Maw that we would eventually end up here. To be frank, I expected you to perish many times over by now. \n\nRegardless, I believe we have all the species we need for our little slice of K'aresh. \n\nNow we just need to work on stabilizing the eco-system and ensuring it thrives.", objectives = "Help with hatching the snakelets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88975] = { id = 88975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spooked Slitherin' Snakes", description = "Somethin' has the snakes agitated again. Spooked even.\n\nHow would ye feel about taking me flute back out there and calming 'em down?", progress = "Sweet music to me ears.", completion = "Thanks for taking care o' that and entertaining the whole o' the Oasis at the same time.", objectives = "Use Hemet's Soothin' Flute to soothe 15 Agitated Snakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88976] = { id = 88976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hope of K'aresh", description = "It is finished. By all measurements, the eco-system in the Oasis is fully stable. While there will always be things we can help with, it would survive if we left it alone. \n\nTake some time and speak with everyone. Congratulate them. Good work should be properly acknowledged.\n\nSpeak with me when you are done.", completion = "The work we have done here can ensure that, with what happened at Eco-Dome: Adani, we can rebuild K'aresh. \n\nIt will take time. So very much time. But I suppose that is the advantage of being immortal yes? Even if it takes tens of thousands of years, my home will be rebuilt. \n\nHopefully, I will be around to see it happen. I have a stasis pod with your name on it, should you have need of it.", objectives = "Talk to your team in the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88977] = { id = 88977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reenact the Crime", description = "Ah, you there! You appear to have the wisdom to assist me, unlike a certain bow-wielding simpleton who thinks sniffing dirt will solve our problem.\n\nWe've accidentally misplaced a very important journal--the sort my mentor would transmogrify me to have lost!\n\nPlease use my arcane timepiece to summon echoes of the past and investigate these moments. That should allow us to find my journal properly, without indulging Vardis's primitive methods.", progress = "Impossible. My magic has never failed me before... It seems we are at an impasse.\n\nTo be thwarted by something so simple, yet so insidiously effective... is infuriating.", completion = "Wonderful--more glowing projections and angry spirits, yet still no journal.\n\nStep aside. I'm ending this nonsense and tracking it properly.", objectives = "Use the Arcane Timepiece to investigate 3 Frozen Moments in the West Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88978] = { id = 88978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Trail", description = "While a certain wyrm-brained mage wastes time with his inept magic, we'll actually solve this case.\n\nThe local wildlife has likely eaten the journal. Time to gut them and see if we can recover it.\n\nIf the journal's inside, we'll find it... unlike someone who couldn't track his own insipid ego if it were carved into the ground.", progress = "What do you mean none of them had the journal? How is this even possible?\n\nIt defies logic! If the wildlife didn't take it, then where in the Twisting Nether could it have gone?", completion = "That fool... That absolute fool.", objectives = "Gather 8 pieces of evidence in the West Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88979] = { id = 88979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught Red-Handed", description = "A dog, of all creatures? This is the thief we've been chasing?\n\nAnd now we must save it from a lynx? Truly, this day has taken a most... irritating turn.\n\nNo matter, we shall retrieve the journal... though I do wonder if this canine truly understands the gravity of its actions.", progress = "Did you manage to retrieve the journal?", completion = "A dog, a lynx, and now a ruined journal. Truly, I've seen lesser misfortunes in my day.\n\n<Meledor pinches the slobbery journal between his fingers.>\n\nIt seems the journal's fate was sealed long before we laid eyes on it. It is quite beyond saving. Once again, my faith in anything other than arcane precision has proven... misplaced.", objectives = "Defeat the Hot-Headed Lynx in the West Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88980] = { id = 88980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who You Gonna Call?", description = "We could do with more slateback essence. \n\nI imagine that the opportunity to keep the sand of K'aresh safe would be right up your alley, yes? \n\nJust bring me back what you find after you are done.", progress = "You have the essence?", completion = "Excellent. We can continue to create more slatebacks now.", objectives = "Collect 10 Slateback Essence in Untethered Space on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88981] = { id = 88981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesting Upkeep", description = "It's time to refresh Ember, Indigo, an' the snakelet's nest. Gotta keep our K'areshi snakes comfy.\n\nDon't worry 'bout carrying anything down there. Just like last time, we'll use one o' Ve'nari's portation tags for that.", progress = "Everything good with 'em? Aren't the snakelets just adorable?", completion = "Great! Glad they're all doin' well. Such a nice, happy family.", objectives = "Refresh the nest of the two named snakes and their snakelets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88982] = { id = 88982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey Contract: Renegade Magister", description = "A RENEGADE MAGISTER has been spotted in Voidstorm!\n\nDifficulty: Normal\n\nAffixes: 0" }
quests[88985] = { id = 88985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recuperating Returns", description = "One of our lightwood loggin' outposts is late with their weapon shipments. Dey used to be punctual, but now we are lacking crucial supplies.\n\nGo check on de camp. Somethin' must be goin' on.", completion = "Another stranger, hm?", objectives = "Meet Woodcrafter Azai at Zeb'Alar Lumberyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88986] = { id = 88986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind the Bandits", description = "Dis elf showed up here seekin' revenge, thinkin' we were responsible for de death of his sister.\n\nBut instead of killin' him, I'm gonna set de boy straight.\n\nDe Amani got no business with some farm!\n\nHe don't understand de Twilight's Blade is attackin' on both sides of de Zul'Aman border!\n\nI don't blame de child. He don't know dat de Twilight's Blade can hide demselves with their void powers.\n\nTake some lightwood splinters. Throw 'em on de shrouded Twilight's Blade. Show him who de real enemy is!", completion = "De boy looks confused.\n\nGood. Maybe he's thinkin'.", objectives = "Kill 8 Twilight's Blade cultists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88987] = { id = 88987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaged Sabotage", description = "Rakani overreacted when de boy came crashin' into camp, but we all have been on edge.\n\nDe Twilight's Blade had already snuck into our camp and sabotaged our work.\n\nIt has already been challengin' to keep up with de demand for weapons. And our people need de weapons to defend themselves!\n\nIf we can get de broken weapons back, we can maybe make up for what we lost.\n\nWhile you deal with dem, see if you can get any of our weapons back--whatever condition dey are in.", progress = "De chaos de elf caused is nothin' next to what we're facin' every day.\n\nWe have to be extra cautious with de Twilight's Blade tryin' to sabotage our every move.", completion = "Thank you. These recovered supplies will help us return our operation to normal.\n\nDespite de elf still bein' around...", objectives = "Retrieve 6 Stolen Equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88988] = { id = 88988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Artisan's Apprentice", description = "Looks like de boy has realized there is more in dis world than his family farm an' de big bad trolls of Zul'Aman.\n\nBut I'm not done with him yet. He gonna learn hard work too. De boy needs to make up for de disruption he caused and de work we lost.\n\nIt'll be a learnin' opportunity--for de both of you.\n\nYou are goin' to make somethin' for us.\n\nPay attention. One wrong move can destroy de lightwood. With de Twilight's Blade sabotagin' our equipment, our resources are too limited already.", progress = "De lightwood is challengin' to work with, even for experienced woodcrafters.\n\nBe patient. Be precise. And do everything I say.", completion = "Hmm. Not bad. For a novice.", objectives = "Follow Woodcrafter Azai's instructions to craft a Lightwood Javelin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88989] = { id = 88989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another One Bites the Sawdust", description = "Dat boy is a fool.\n\nBut he's a courageous fool.\n\nIt's time to test dis weapon you crafted.\n\nHe'll be goin' after their commander. He's killed many of my crafters, but revenge is not worth his life or dat of anyone else.\n\nGo after him before he gets himself killed.\n\nI did not go through all dis trouble just for him to die now, eh?", progress = "Dat commander killed some of our own.\n\nHis troops most likely killed de boy's sister.\n\nBut even though killin' him would make craftin' weapons and sendin' dem back to Amani'Zar easier, it's not worth dat boy's life.", completion = "You saved de boy's life. And maybe now he will think before he rushes off and makes a life-endin' decision.\n\nAnd eliminatin' de head of de sabotage ring will allow us de time to make all de weapons we need.\n\nThings tend to work out for de best, eh? Even for you.\n\nHere's a little somethin' de crew and I want you to have.", objectives = "Kill Covert Commander Tofir and rescue Kellor Sunshimmer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88992] = { id = 88992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envisioned Mastery" }
quests[88993] = { id = 88993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wey'nan's Ward", description = "To claim this relic, travel to the Vale of Secrets. Seek the Visionstone. Its surface bears sacred paintings, with a hand print aglow at the center.\n\nPress your hand upon it and let your spirit be known. Your body will falter into trance, and your soul will walk visions of the past.\n\nBe warned: these visions are no mere dreams, and the dangers within may strike true.\n\nReturn to me with the wisdom you uncover.", progress = "Has your journey revealed the truth of Wey'nan's Ward? Share what you have uncovered.", completion = "An incredible tale, worthy of preservation. I will set it into paint, ensuring it lives forever within the echoes of our people. Accept this memento--a token of my gratitude for your efforts.\n\nFor now, I will continue to go through our archives, seeking relics that cry out for understanding.\n\nReturn to me when the world has whispered more secrets to you.", objectives = "Travel to the indicated shrine in Harandar to meditate and experience the history of Wey'nan's Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88994] = { id = 88994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cauldron of Echoes", description = "For untold eons, the Cauldron of Echoes has rested in shadow, its purpose obscured by time.\n\nWhen I first walked the path of the Zur'ashar, my master spoke of its significance--a relic tied to the very origins of our kind. Yet its secrets eluded even them... a mystery left unanswered.\n\nNow, it calls to us once more.\n\nWill you uncover what has been forgotten? The truth waits within, and I would be forever grateful for your discovery.", progress = "Has your journey revealed the truth of the Cauldron of Echoes? Share what you have uncovered.", completion = "What a remarkable story!\n\nHow ironic that the tale of Sai'alyo, the first of the Zur'ashar, was lost to time. Your efforts bring us closer to understanding this vital piece of our history.\n\nPlease, accept this keepsake as a mark of my gratitude for your dedication.\n\nFor now, I will delve deeper into our archives, uncovering relics that still long for discovery.\n\nReturn when the whispers of the world guide you back to me.", objectives = "Travel to the Glade of Walking Memories in Harandar to learn the history of the Cauldron of Echoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88995] = { id = 88995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aln'hara's Bloom", description = "When I was young in the path of a Zur'ashar, I heard a tale of a gift from Aln'hara: \"A sign of the goddess, felt in the stillness.\"\n\nUnfortunately, all those who were there to experience the event eventually passed on before we learned the secrets of our special paint.\n\nWould you walk the memory that surrounds the bloom and find out if this theory is true?", progress = "Tell me what you witnessed, and we will ensure the memory is not lost again.", completion = "What a gentle truth you have uncovered! Aln'hara did not speak with thunder, nor return in form, but in patience, she revealed her presence.\n\nYou have given voice to the voiceless, and in doing so, restored a moment to our people.\n\nPlease, take this token as a symbol of your journey.\n\nAnd should the world grow quiet once more, return. I will be listening for the next whisper.", objectives = "Travel to Veilroot Clearing and uncover the truth behind Aln'hara's Bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88996] = { id = 88996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Echoless Flame", description = "The Echoless Flame's fate is lost to time. Down through the ages, it was whispered that the lantern contained the power of Aln'hara herself. But now, it lies dormant--a shell without even a flicker left within.\n\nPerhaps you can uncover its secrets where others have failed?\n\nRetrace the steps of Obayo, the first of the Shul'ka, and bear witness to the glory of the relic and its true purpose.", completion = "The flames were exhausted to keep that monstrosity from destroying us all?! I'm given to understand the creature is now known as Morta'ka the Sundered Echo. How fitting.\n\nThis is both a blessing and also most unfortunate. How different might the Rift of Aln be today if the flame still danced within the lantern?\n\nPlease return soon, {name}. You and I have more to uncover.", objectives = "Travel to the Verdant Sepulcher in Harandar to learn the history of the Echoless Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88997] = { id = 88997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Russula's Outreach", description = "A weather-worn spear haft, laced with pale mushroom threads, rests in silent vigil. The elders name it Russula's Outreach, yet no tale agrees on what that outreach was, or whom it spared.\n\nWas this weapon raised in fury, or lowered in mercy?\n\nThe relic offers no answers here, only a lingering pull toward the old culling grounds.\n\nFollow that pull. Trace the footsteps lost to rot and rumor, and let the visions speak of what history forgot.", progress = "Has your journey revealed the secrets of Russula's Outreach?", completion = "Russula's plea, \"Do not kill them,\" echoes far louder now that we have seen the lengths he walked, and the wounds he bore, to keep Harandar from tearing itself apart. His act tempers our own culling creed with a needed measure of mercy.\n\nYour steps restored this forgotten balance, {name}. Take this keepsake with my gratitude, and return when the land calls again. There are surely more quiet truths waiting beneath the spores.", objectives = "Travel to the Verdant Sepulcher to learn the history of Russula's Outreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[88998] = { id = 88998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root of the World", description = "The Root of the World is the first gift of the land to the haranir, or so it has been said. We have forgotten much about how the staff came to be in the possession of my people. But the root of the story, if you will permit, begins at a time not long after the haranir first came to Harandar.\n\nI trust that together, we can uncover its lost past.\n\nIt is known that Ruilla the Huntress was a pivotal figure in the events that led to the creation of the staff. Go and see history through her eyes.", sourceObjective = "Travel to the Vale of Secrets to learn the history of the Root of the World.", progress = "Have you learned about the Root of the World? What truths have you uncovered?", completion = "What a fascinating history! Ruilla the Huntress took up the staff to become both the first Rootwarden and the first of us to walk the Rootways.\n\nIt is sad to reflect that while much has changed in the world above, much has not.\n\n{name}, please come back to me when the land once more guides you to do so.", sourceObjectiveStatus = "unverified-source-field" }
quests[88999] = { id = 88999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sky's Hope", description = "Sky's Hope: the stone that legend says fell from the sky. Little is known about it besides it being considered a symbol of hope.\n\nBut why?\n\nFollowing in the path of our ancient ancestor, Awe'ohna, might shed some light on the matter.", sourceObjective = "Travel to the Shrouded Grove in Harandar to learn the history of Sky's Hope.", progress = "Back so soon? What mysteries of Sky's Hope have been revealed?", completion = "Could it be that Awe'ohna found the hope he was after in seeking out the Cradle?\n\nIt's true the goddess returned and the sky is no longer darkened, but how? And did he actually make it?\n\nIt would seem our answers have led to even more questions.", sourceObjectiveStatus = "unverified-source-field" }
quests[89012] = { id = 89012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Safe Path", description = "We must rescue the civilians and get them to the ships, yet the path to the docks is barred by a vile, hungering creature.\n\nIf we are to save my people, then we need to clear an evacuation path. We cannot leave them to fend for themselves.", progress = "Does the engulfing Void still bar the way?", completion = "Thank you, {name}. These rescue missions are rarely as straightforward as they seem. There is always one more threat that appears that you didn't account for.", objectives = "Eliminate Gloomstress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89016] = { id = 89016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Members Only", objectives = "Welcome to the Club! Whether it's playing or slaying you're after, our loyalty program will outfit you with the finest perks the Gallagio has to offer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89018] = { id = 89018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyal Customer: Silver", objectives = "You're movin' up in the world! Let's get you an upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
