quests[89022] = { id = 89022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyal Customer: Diamond", objectives = "You're movin' up in the world! Let's get you an upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89023] = { id = 89023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loyal Customer: GOLDEN LEGENDARY!!!", objectives = "That's the last one we got! You're on top of the world, sweetheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
