quests[89027] = { id = 89027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fast Food", objectives = "You want that to go? Have it your way!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89028] = { id = 89028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chip Service", objectives = "Compliments of the house! Take this to the nice Hobgoblin just across the way and pick yourself up somethin' nice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89029] = { id = 89029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chip Service", objectives = "This is the last one I got! Sando'll make sure you're blinged out - but maaaaaybe you might find a few more around the casino...", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89032] = { id = 89032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with The Singularity", description = "You continue to show us that you are an integral member of our community. \n\nTo honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.", sourceObjective = "Speak with Murik in Iskaara.", sourceObjectiveStatus = "unverified-source-field" }
quests[89034] = { id = 89034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Bitterblooms", description = "Lightbloom-infested rutaani are working to spread the contamination through the village. This plant showed significant signs of the disease.\n\nDestroy any of the plants they've come into contact with. We must contain this!", progress = "The Lightbloom cannot be allowed to spread. The harmony of Har'mara is delicately balanced. We must keep it intact.", completion = "Well done, {name}. May Har'mara return to the peaceful oasis it was when we arrived.", objectives = "Destroy 6 Lightbloom-Infected plants in Har'mara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89035] = { id = 89035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Hara'ti", description = "The Hara'ti are stronger for what you have done.\n\nGo to Naynar. She will see that your deeds are remembered, and present you trophies appropriate for all you have done.", sourceObjective = "Speak with Naynar in the Den.", sourceObjectiveStatus = "unverified-source-field" }
quests[89039] = { id = 89039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turbo-Boost: Powerhouse Challenges", description = "<Undermine has a problem. Here's what we need. An established group, or just a bunch a ya really, ready to help out our pals in Undermine. Help clear out the worst of the competition, and we'll make it worth your time.\n\nComplete the task, and collect a special reward from Consultant Wrexxle outside of the the Dornogal Treasury. Limited time offer. Some restrictions will apply.>", progress = "Yous looks out for us, and we return the favor. Right?", completion = "Thanks, pal. Undermine is a mess right now. We'll take all the help we can get.\n\nAnd hey, a deal's a deal. Here's what we owe.", objectives = "Defeat any four bosses within The Liberation of Undermine raid on Looking For Raid difficulty or higher, or complete any four Mythic Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89056] = { id = 89056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ray-ket Ball, Redux", description = "Time again to test the reflexes of our newborn. \n\nPerhaps you could play more ray-ket ball?", progress = "You are doing me a great service by exercising that pup.", completion = "Ah, yes. Excellent. That pup is coming along nicely.", objectives = "Catch a ball 10 times while playing with your Necroray Pup.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89057] = { id = 89057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pee-Yew de Foxy", description = "{name}! Are you ready for a repeat adventure in olfactory excellence?\n\nI've whipped up another concoction for the thorntails. This one's definitely an improvement over the last batch.\n\nWould you be the best and go give it a try?", completion = "Just as I expected. Better than last time! Om'talad will be pleased to receive the data.\n\nI'll get to work on improvements to the formula right away.", objectives = "Douse 8 Regal Thorntails in pheromones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89061] = { id = 89061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", completion = "An impressive kill. An even more impressive trade.\n\nYou will be rewarded. I will not have myself in your debt.", objectives = "Deliver the Crystallized Anima to Ve'nari in the Oasis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89062] = { id = 89062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", completion = "An impressive kill. An even more impressive trade.\n\nYou will be rewarded. I will not have myself in your debt.", objectives = "Deliver the Crystallized Anima to Ve'nari in the Oasis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89063] = { id = 89063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", completion = "An impressive kill. An even more impressive trade.\n\nYou will be rewarded. I will not have myself in your debt.", objectives = "Deliver the Crystallized Anima to Ve'nari in the Oasis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89065] = { id = 89065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ray-cing for the Future", description = "Looks like we've got another feisty necroray on our hands! Want to tire it out?", progress = "Watch it out there. That one moves quick!", completion = "My old bones ache just looking at ye tearing around like that!", objectives = "Challenge the Zooming Necroray to a race and reach the finish line.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89192] = { id = 89192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hard Day's Work", description = "We are running low on void shields. Your assistance is required to make a new one. \n\nMeet me outside the dome to the east. We shall craft it together.", progress = "Come now. Let us begin.", completion = "Your ability to throw me the correct items is very valuable. You would not believe how frequently people lack that skill.", objectives = "Assist Ve'nari in crafting a void shield outside the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89193] = { id = 89193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arator", description = "Archbishop Alonsus Faol has left a message asking to speak with you in regards to a project to help Arator and the Vanguard of Light.", completion = "Thank you for coming, {name}. I need your help, as do many of our priests and paladins.\n\nOne paladin in particular.", objectives = "Speak with Alonsus Faol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89194] = { id = 89194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shake your Bee-hind", description = "{name}--just the {race} I wanted to see! I need you to go dance for m--I mean, bees. \n\nI shall just watch you leave now.", progress = "<Alaenra appears to be silently dancing to a beat only she can hear.>", completion = "The bees already know where the plants are these days, but it cannot hurt to remind them.\n\nAlso, I do like watching you dance.", objectives = "Dance for the bees in the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89195] = { id = 89195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funny Buzzness", description = "I seem to bee running low on bee puns at the moment, but I do need more bees from Stormsong Valley. Would you bee a dear and collect them for me?", progress = "<Alaenra appears to be making sucking noises while holding an imaginary vacuum.>", completion = "As always, your assistance is appreciated. What? I can't drop puns every time, you know.", objectives = "Vacuum up 20 Honey Bees to K'aresh while in Rosaline's Apiary in Stormsong Valley on Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89197] = { id = 89197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ray Ranching", description = "Ah, there you are. I need to perform medical checkups on the necrorays, and I could use some assistance in capturing them. Perhaps you could help?", progress = "Have you captured the necrorays I require?", completion = "Thank you. For one with less limbs, you are certainly more coordinated.", objectives = "Lasso 6 Tranquil Necrorays and bring them to the Hitching Post by Om'talad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89198] = { id = 89198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dry Cleaning", description = "Aw heck! The k'arrocs are acting all feisty again. \n\nMind giving them a good clean so their natural aroma can rise to the top?", completion = "Thanks, buddy! \n\nHave you considered getting into scents? Your aroma is real strong!", objectives = "Wash 10 Domineering K'arrocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89199] = { id = 89199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Task", description = "You will forgive the lack of pleasantries, as this situation requires prompt remediation.\n\nAll you need know is that I am Aradis, wardsmith of Silvermoon. We are an order of Magisters who maintain the city's defenses.\n\nI am recovering from a... minor battle injury, and require aid charging my wardbreaker staff. You will be compensated, and perhaps provided additional opportunities to aid me.\n\nI can furnish the details as you work, so long as you are not terribly slow.", progress = "Do handle the wardbreaker carefully. I will not tolerate seeing it damaged.", completion = "Making yourself useful is a prized quality in Silvermoon. You are well on your way.", objectives = "Collect the Depleted Wardbreaker, then charge it using 4 arcane reservoirs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89200] = { id = 89200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unraveling Wards", description = "Dawnblaze is keeping the blackmail documents in her study. It is highly warded, naturally.\n\nThe wards themselves are pitifully made. However, she is supplying additional power to them using arcane conduits placed throughout the city. I found the first link in the chain and brought it here to study.\n\nIt is also warded, but weakly. I theorize that if the conduits are broken in sequence, then the shields on Dawnblaze's study will be vulnerable.\n\nSabotage them, then recover the documents. Understood?", completion = "As expected, my theory has been proven correct.\n\nThe only task that remains is breaking the final ward and removing those documents from Dawnblaze's possession.", objectives = "Use the charged Wardbreaker to destroy the shields guarding 5 Warded Conduits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89201] = { id = 89201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outschemed", description = "The entrance to Dawnblaze's study is in the terrace just beneath us.\n\nSince my magic can project this close to her wards, that means the magic guarding this place has been weakened... as I predicted.\n\nBreak the larger ward sealing the entrance and find the documents she forged to slander me. I will expect your expedient return to my office thereafter.", progress = "I will be taking those documents back.", completion = "You ought to be more careful with the affairs in which you entangle yourself.", objectives = "Use the Wardbreaker to enter Magister Dawnblaze's study, then find the Incriminating Documents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89202] = { id = 89202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stir the Nest", description = "Aradis told you the blackmail was false? Of course. He is vying for my position. These receipts would ruin him.\n\nHe is a warlock, and we have rules about fel magic. It is not banned, but it must be used discreetly. Aradis is not discreet. Magic misuse, unsanctioned demons, fel smuggling, bribery... His list of crimes is long.\n\nBut you need not take my word for it. Aradis has earned many enemies in the city. If you can find him in the Row, a man named Jaeth could tell you all about our dear warlock.", completion = "Gonna assume you have a particular type of business if you're asking for me by name. So spit it out.", objectives = "Question 8 Row Rats about Jaeth's whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89203] = { id = 89203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutual Benefit", description = "<Jaeth waves a hand to cut you off as you explain.>\n\nAll right, Dawnblaze sent you. That means there's a job. Not surprised she doesn't want to dirty her robes coming to the Row herself. The types who hire us never do.\n\nEveryone that high up in Silvermoon backstabs each other. When it's literal, they pay us to do it for them. They get whatever power they're chasing, and we get enough coin to live another week.\n\nWhose back is getting a knife this time?", progress = "Come on. Spit out the details.", completion = "He tried to take me last week too. I shanked him in the gut before he ran.\n\nI chased him, but his place down by the harbor was warded with fel magic. If Dawnblaze has a way inside, I'll happily finish him off.", objectives = "Show Jaeth the incriminating documents about Aradis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89204] = { id = 89204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Five Finger Discount", description = "Aradis gave you his wardbreaker? What an idiot. Those get sold on the black market as skeleton keys. Expensive, but you have to attune them to the magic you're breaking, which isn't easy.\n\nLooks like yours is empty. We can fix that. If we pocket a few magic valuables around the city, my buddy upstairs can disenchant them and get that wardbreaker juiced with fel magic.\n\nAradis won't have anywhere to hide then.", progress = "This is the easy part.", completion = "Nice and clean. I've been stealing to make ends meet since I was a kid, but I don't get a partner in crime very often.", objectives = "Help Jaeth pocket magical items from shops in the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89205] = { id = 89205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting a Key", description = "I told Zanien here the whole story. He's been training warlocks for a long time--and if anyone hates sloppy ones, it's him.\n\nHe's confident he can get the wardbreaker recharged. Follow his instructions and we should be good to head out afterward.", progress = "That staff should be able to break this ward now.", completion = "I'll be surprised if Aradis isn't already holed up here. But if he isn't, I'm sure we'll see him soon.\n\nWards this fancy always have alarms woven into them.", objectives = "Attune the Wardbreaker to fel magic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89206] = { id = 89206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break and Enter", description = "Can you hear that? It sounds like it's coming from downstairs. Like someone's in pain.\n\nThe last kidnapping from the Row was pretty recent. This could be where he's been keeping the people he took.\n\nMy people. My friends.\n\nEven if Aradis doesn't show his face, we're not letting him keep them here. Bring this ward down. We're going in.", progress = "We're getting them out of here.", completion = "<Jaeth feels Sarvi's neck for a pulse, then sighs angrily.>\n\nShe's already gone. I know her brother. I'll make sure she gets returned to him.\n\nBut first, we'll make Aradis bleed.", objectives = "Destroy the fel magic warding Aradis's private study.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89207] = { id = 89207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rats Can Bite", description = "I know all of these people. They're workers, not fighters. Aradis went after the ones who couldn't fend him off. That's why he ran when he tried to take me and realized he picked the wrong target.\n\nAfter the trouble we've made, there's no way he doesn't know we're here.\n\nBe on guard. Once he shows his face, he's dead.", completion = "The Row will always be in danger, so long as Silvermoon turns a blind eye to us.\n\nBut for now, we're a little safer. Good riddance.", objectives = "Kill Magister Aradis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89208] = { id = 89208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We're Owed", description = "Everyone out here should be fine. Sarvi... I'll get her back to the Row. If we leave her here, the guards will just have the body tossed.\n\nI hope they do the same to Aradis, but I'm sure they won't.\n\nCome on. Let's go talk to Dawnblaze and get our payment. I remember where her office is.", progress = "I see you recruited our dear assassin to the cause. Well done.", completion = "It was a pleasure working with you, {name}.", objectives = "Inform Magister Dawnblaze that the job was completed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89209] = { id = 89209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bu-zzz", description = "These bees are absolute workhorses--workbees? They are worker bees so I suppose... ah, apologies for my distraction.\n\nSeveral of the bees have tired themselves out. Can you return them to the hive?", progress = "Goodness! They're terribly busy, aren't they?", completion = "You've finished? Then buzz off!\n\nA pun! Merely a pun!", objectives = "Pickup 10 Overworked Honey Bees and return them to their hive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89210] = { id = 89210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Photography is the Bee's Knees", description = "All right, {name}. Take this camera and this film. You've done this before. It's time for documentation!\n\nI know you are practically buzzing to get out there, but it's time to bee focused.", progress = "Photographing bees is marvelous when someone else does it.", completion = "Simply bee-utiful. This photo is a keeper!", objectives = "Document 15 Honey Bees and the Queen Bee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89212] = { id = 89212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royal Photographer", description = "<Om'talad is intently taking several photos of himself.>\n\nAh! {name}! We need to update our documentation of the thorntails. \n\nThis camera I was... testing appears to be functioning correctly. Please go update our documentation.", progress = "<Om'talad appears to be engrossed in some data from the console and is actively avoiding your gaze.>", completion = "My thanks for the update. Perhaps we omit what happened earlier from any reports to Ve'nari?", objectives = "Document 10 Regal Thorntails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89213] = { id = 89213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flights of Fancy", description = "We are in need of new photos of the k'arrocs for our records. Please take some for us while you are out in the eco-dome.", completion = "Excellent. You show much talent for image capturing. Thank you.", objectives = "Document 7 Domineering K'arrocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89221] = { id = 89221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leafing Things on the Ground", description = "I woke up today and thought to myself, \"That platter of food {name} put out for the lapbugs was excellent. I suspect the lapbugs would like it if {name} did that again.\"\n\nWhy don't you make that happen, hmm?", progress = "Have you fed the lapbugs yet?", completion = "Thanks, {name}. You are a leaf saver.", objectives = "Collect 7 Chopped Oasis Plant cuttings and then place 3 Plant Platters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89222] = { id = 89222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnant of Azeroth", description = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt.\n\nKul Tiras calls out to you.", completion = "A remnant of Azeroth from a time of conflict and strife. Such a troubled artifact has no place in the timeways, thank you for returning it.", objectives = "Bring the Remnant of Azeroth to Churbro in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89223] = { id = 89223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnant of Azeroth", description = "Upon first glance it appears to be a crystallized shard of Azeroth's life blood. Peering into the shard reveals visions of war across familiar fronts, countless lives locked in battle. The sounds of thunderous storms and crashing waves begin to overwhelm you, before coming to an eerie halt.\n\nZandalar calls out to you.", completion = "A remnant of Azeroth from a time of conflict and strife. Such a troubled artifact has no place in the timeways, thank you for returning it.", objectives = "Bring the Remnant of Azeroth to Churbro in Dazar'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89230] = { id = 89230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lover Not a Fighter", description = "De elders are plannin' a festival to give thanks to de loa. I wanna ask Namaji to accompany me but....\n\nIt is tradition that a suitor give a gift that proves their prowess as a warrior. But I am a poor fighter and de others laugh at me because of it.\n\n<Kagara hangs his head dejectedly.>\n\nPerhaps you can help me? I know Namaji has always wanted a threshadon tooth necklace. De gnarldin make dem, but only de strongest have one.\n\nCould you find one for me and deliver it to her on my behalf?", progress = "Did you need somethin'?", completion = "Dis is from Kagara? I've always wanted one of these!\n\nI'd be happy to go to de festival wit' him. I'll finish my work here first and den go tell him myself.\n\nThank you for deliverin' dis!", objectives = "Collect a Threshadon Tooth Necklace from the gnarldin at Akil'zon's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89231] = { id = 89231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fighter Not a Lover", description = "You goin' to de loa festival? Young trolls like me are expected to ask someone dey like to go wit' dem. And to give a gift to show their worthiness.\n\nI wanna go wit' Namaji. I'm a great fighter, but I'm sure there are many other warriors dat wanna go wit' her!\n\nThey'll gift her trophies and spoils. But I'll be different.\n\nI think she'd like a headdress, but I have no idea how to make one. Could you make a feathered headdress for me and give it to her?\n\nYou can find feathers at Akil'zon's Reach.", progress = "Another gift?", completion = "A lovely headdress! From Zak'kash? Oh...\n\n<Namaji looks troubled.>\n\nBoth Zak'kash and Kagara want me to go wit' dem to de festival. What should I do?", objectives = "Collect 8 Eagle Feathers from Akil'zon's Reach and make an Amani Headdress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89233] = { id = 89233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love Triangle", description = "It seems we have a problem: Kagara and Zak'kash both wanna go wit' me to de festival! Which one do I choose?\n\nI like both of dem well enough. Please {name}, you need to help me! What do you think?", progress = "Dey are both good choices...", completion = "Thank ya for helpin' me. Kagara, Zak'kash... I hope we can all still be friends after dis.\n\n<Namaji furrows her brow but then smiles.>\n\nI best go tell my festival partner of my decision den! Thank you again.", objectives = "Help Namaji decide who to go to the festival with.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89238] = { id = 89238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow-up Appointment", description = "There is much medical data to be gleaned in the evaluation of the k'arrocs.\n\nPlease take the condenser disc to shrink them and then pick the little ones up for easy transport.", completion = "Thank you again. These k'arrocs will do quite nicely.", objectives = "Shrink and collect 8 Domineering K'arrocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89240] = { id = 89240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream-Dream-Dream-Dream-Dreameringeding!", description = "We need to check how the thorntails are progressing. Would you be so kind as to gather more blood samples?\n\nAs before, use the darts to put them to sleep and then retrieve the dart with the blood on it.", completion = "Excellent work. I shall proceed with the examination of these samples immediately.", objectives = "Collect 5 Blood Samples from Regal Thorntails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89241] = { id = 89241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up and Up" }
quests[89242] = { id = 89242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Want a Golden Ooze!", description = "It seems our custodians have been lax in their duties once again.\n\nTake the vacuum device. Clean up the lumps. I will cut you a percentage of the returns.", progress = "How go your efforts?", completion = "You never disappoint, {name}. Mostly. As promised, here is your cut.", objectives = "Clean 25 Congealed Lumps in the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89249] = { id = 89249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelmed", description = "We were too late. All of the strength between us wasn't enough.\n\n<Arator looks over his shoulder, wary. Then, he crouches and places his hand on Alleria's shoulder. She responds only with a ragged exhale.>\n\nLet's fall back. The ren'dorei have been exploring the wilds while we've been following Lothraxion. We might be able to find their encampment nearby.", completion = "Even the power of a naaru wasn't enough...", objectives = "Reconvene with Arator at Locus Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89250] = { id = 89250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Rubber", description = "<Few things are as exhilarating as unbridled speed, and few things are as respected as the G-99 Breakneck in Nanny Talullah's garage.\n\nMobber will certainly know how to tune your ride with the new part.>", completion = "You ready to tune that ride of yours?", objectives = "Speak with Mobber to tune your G-99 Breakneck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89251] = { id = 89251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Hot!", objectives = "Paula said you were on a real hot streak - why don't we turn up the heat?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89252] = { id = 89252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need a Jump?", objectives = "It's gruesome work out there on the floor, so your friends outside sent you a pick-me-up! Literally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89254] = { id = 89254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutterbug", description = "The pictures with the lapbugs were a smash hit. We need more of them for marketing.\n\nSorry, {name}. In this case, the lapbugs with hats are more in-demand than you. Do not be sad though. At least you're getting paid while also getting your face out there, yes?\n\nNow, get clicking.", progress = "Consider making the shots more interesting with your own wardrobe changes.", completion = "Excellent. I shall send these out immediately.\n\nDo not stray too far, {name}. We will need your keen eye again soon enough.", objectives = "Take a S.E.L.F.I.E. with various lapbugs that are wearing hats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89263] = { id = 89263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Cut of the Spoils", objectives = "You {name}? Got something for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89267] = { id = 89267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Entity" }
quests[89268] = { id = 89268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Legends", description = "Among these walls lie relics, silent and forgotten, their stories obscured by time.\n\nThe path to reclaiming our past is clear: take a relic to the sacred shrines and step into the echoes of its history. The visions will guide you, letting you walk the tale firsthand and breathe life into memory once more.\n\nIf you would lend your spirit to this cause, choose a relic to reawaken its story.", completion = "So be it. Your path is set. This relic's truth awaits you.", objectives = "Select a relic to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89271] = { id = 89271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Son", description = "One moment, {name}. I have a personal matter. I would like you to find my son, Arator. He is a member of the Silver Hand, an accomplished paladin. \n\nI know he must have been called. His faith is strong. The Light would want him here fighting against Xal'atath.", progress = "Have you found my son?", completion = "You found him? Thank the Light!\n\nWe can't afford distractions. I need Arator here with the assembled forces, fully focused on the assault against Xal'atath.", objectives = "Find Arator and bring him to Turalyon at Light's Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89274] = { id = 89274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ugly Mirror" }
quests[89276] = { id = 89276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Snacks", description = "Classics are classic for a reason, darling. One simply cannot host a worthwhile soiree without a fine selection of mana for one's guests to indulge in.\n\nThe Magisters could bring some, but mana is best when freshly siphoned. The mana wyrms in southern Eversong have a decadent brightness to them that I find particularly lovely.\n\nBe a dear and gather some for us.", progress = "Time is of the essence, dear.", completion = "Ah, this shall do very nicely.", objectives = "Siphon magical energy from 6 Scintillant Wyrms in the Tranquil Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89277] = { id = 89277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illuminate the Space", description = "I share our dear Saltheril's love for vintage fixtures, but the lighting enchantment he is using is far too common for such an auspicious occasion.\n\nMy Magisters can create a far more stunning enchantment. Simply gather some fibers from the Lightbloom for me and I can have them broken down into spell reagents.\n\nThe effect will be marvelous.", sourceObjective = "Gather 8 Luminous Fibers from creatures near Lightbloom Ath'Ran.", progress = "We need only a small quantity. Our spellwork is quite efficient.", completion = "Well done, my dear. We shall have the Haven sparkling in due time.", sourceObjectiveStatus = "unverified-source-field" }
quests[89278] = { id = 89278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minding Our Duty", description = "While the court does demand our consideration, we cannot forget duties. Our guests will enjoy themselves more freely if they are assured of the solidity of Eversong's defenses.\n\nThe Magisters are tasked with maintaining the runestone wards throughout Eversong. Please survey them for us and let us know if any wards need our attention.", completion = "My dear, you are delightfully meticulous. I will assure the court that they need fear nothing.", objectives = "Inspect the integrity of 4 Runestone wards around Eversong Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89285] = { id = 89285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Favor" }
quests[89288] = { id = 89288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Riftbreaker Tza'akir" }
quests[89289] = { id = 89289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor of the Court", description = "Ah, {name}, my favorite {class}! I am delighted to see you in attendance once more.\n\nYou have quite the natural talent for these sorts of affairs. The nobles are pleased with your presence and your favor has been swaying their coffers.\n\nLet us not stop a good thing, shall we? Help me choose an ally of our representatives to invite to the Haven this week. I'm ever curious to see the drama you will stir up.\n\nAs my personal guest of honor, your favor will be seen as an extension of my favor.", completion = "Excellent choice.\n\nI will have my valet send for them at once.", objectives = "Choose an ally of the Magisters, Blood Knights, Farstriders, or Shades of the Row to invite to Saltheril's Soiree this week.\n\nYour choice will determine which faction will offer \"Fortify the Runestones\" to your Warband this week.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89291] = { id = 89291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phase Diving: Oath-Breaker Desamirah" }
quests[89293] = { id = 89293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Overshadowed" }
quests[89294] = { id = 89294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Aligned Views" }
quests[89295] = { id = 89295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flame Burns Eternal", description = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades.\n\nCan we count on your continued support in the battles ahead?", progress = "Ready yourself soldier, the battle is still to come.", completion = "You've bought us a moment of peace.\n\nRest well, but always keep your blade sharp.", objectives = "Complete the Nightfall scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89297] = { id = 89297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not as Cute When They Are Bigger and Angrier", description = "It seems there are some who are looking to adopt lapbugs. Adoptions mean more revenue.\n\nUltimately, this benefits the Oasis. Please acquire more essence for me.", progress = "Have you performed the task?", completion = "Very good, {name}. Your efforts are as appreciated and necessary as ever.", objectives = "Collect 10 Lapbug Essence in Untethered Space on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89307] = { id = 89307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Favor" }
quests[89311] = { id = 89311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Favor" }
quests[89314] = { id = 89314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saltheril's Favor" }
quests[89317] = { id = 89317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children's Week in Dornogal", description = "Oh, hello! You must be {name}. I can't thank you enough for stopping by to help with these little ones. \n\nSince we earthen don't have children of our own, I thought it would be fun to help some of our allies out for the week, but it turns out children are quite... energetic. I also don't have a good grasp of what children find \"fun\" yet.  \n\nIf you could take the kobold youngling with you that would be helpful. They seem to have somewhere they want to visit.  \n\nTake this whistle to call them to you.", completion = "<Skibbles looks at you in awe, then seems to realize she's staring.>\n\nWow, you bigger and taller than kobold friends. Hello Big-Tall, my name Skibbles!\n\nMe hear you are very brave, Big-Tall. Skibbles want to be just like you! Talk-Rock say you here to help Skibbles.\n\n<Skibbles lets out a comically large gasp, her eyes going wide as if she suddenly remembered something.>\n\nYou here to take Skibbles on an adventure?? Me always want to go on adventure! Dis gonna be best day ever!", objectives = "Speak to the orphan, Skibbles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89318] = { id = 89318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bold for a Kobold", description = "Big-Tall! Nice Talk-Rock tell Skibbles that she get to do whatever she want today! \n\nWell, me have big dream. One so big, me get in trouble for it. A lot. \n\n<Skibbles takes a deep breath.> \n\nMe want to be brave candle knight, like shiny humans with floaty boats! \n\nA-and me hear there is crystal that's brighter than any candle! \n\n<Skibbles pauses, seemingly anticipating rejection.> \n\nWould...would you take Skibbles to see candle knights with big kitties?", progress = "Oh, hello {name}. I've had a wonderful time chatting with the orphanage patron here. After watching the children play, I am starting to see why my previous activities weren't as exciting for the younglings I am watching. \n\nThey do not seem as interested in city tours but instead have an incredible capacity to pretend! Fascinating. \n\nOh, I almost forgot--did you get a chance to take Skibbles to see the Lamplighters?", completion = "My goodness! I have never seen Skibbles this excited! It sounds like she made quite the impression with the Lamplighters. \n\nSpeaking of children, I was watching the other Arathi children play and noticed that Destien seems more interested in his book than joining in.  \n\nPerhaps you could talk to him? Surely there is something he would rather do than stay here.", objectives = "Take Skibbles to Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89319] = { id = 89319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wondrous Weave", description = "<Destien looks at his feet as you approach.>\n\nH-hello! I'm Destien. Earthen Matron Ullna told me about you, and said you are an adventurer! You must have seen all kinds of spooky and awesome things, right?\n\nT-there is one thing I would like to do, but I'm worried it will scare people.\n\n<Destien looks around nervously and lowers his voice.>\n\n I've heard there are good nerubians and that you've met them! I've always wanted to talk to one but they scare me.\n\nWould you come with me to meet them?", progress = "My goodness! The nerubians certainly have an interesting society. The younglings seem to be very different than the Arathi children, even though they're similar in their desire to play and get into trouble. \n\n<Ullna smiles fondly.>", completion = "My, look at Destien!  \n\nI don't think he's ever talked so much before. The nerubians must have left a strong positive impression on him indeed.  \n\nI can't wait to hear what he's learned by spending some time with you today. Who knows? Perhaps this is a small start to a better understanding between the two races. \n\nOh! The nerubian youngling, Threadis, has been eagerly awaiting you. They don't speak yet, which is common for young nerubians, but they can still communicate using other methods.", objectives = "Take Destien to the Weaver's Lair to meet the Widow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89320] = { id = 89320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eager Engineer", description = "<Threadis looks up at you nervously. \n\nThey hold up what appears to be a drawing of a goblin rocket, similar to the rocket drill going to Undermine. \n\nPerhaps they would like to ride the rocket drill to Undermine located in the Ringing Deeps?>", progress = "My, this place is certainly different! It's almost the complete opposite of the Weaver's Lair. Not to mention all the colors... and smells. \n\nIt has been fun to watch the goblin children at play, though. They have more in common with the Arathi, kobold, and nerubian children than I would have imagined!  \n\nThey're certainly a handful...", completion = "Would you look at Threadis! I know they are very proud of that little bot they built, so I'm glad they were able to bring it to a place where their talents are appreciated. \n\nI'll stay here and see if I can have a chat with Professor Neltik. Why don't you take Kitzy? We'll meet you in Dornogal when you're finished!", objectives = "Take Threadis to visit the rocket drill in the Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89321] = { id = 89321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recreation for Rooks", description = "Hey! You're {name}, ain't ya? My name's Kitzy! Man am I sure glad to see you. \n\nLook, I really wanna go back up to the surface to the stone city. The air is so clean and the sun is so bright!\n\nI also saw a giant blue bird fly overhead, except it had lots of legs! Ullna said it was called a...ruk? Rock? Somethin' like that.\n\nAnyway, I wanna see one! I ain't never seen anything so pretty before. Do you think I can pet one?\n\n<Kitzy gasps, her eyes shining in excitement.>\n\nDo you think I could RIDE one?", progress = "<Ullna notices you approach and beams excitedly.> \n\n{name}, look at all of these people! They're here asking about the children we've been watching. I can't believe it. This is so exciting! \n\nLet me know when Kitzy's ready to return. We have much to discuss.", completion = "Kitzy did what? My goodness, I would have never thought to do something like that. Children are truly astounding. The bounds of their playfulness and creativity seem limitless.  \n\nThis has been such an eye-opening journey. I think I understand children a bit better through speaking to the other caretakers and especially through all you've done. \n\nI can hardly believe it, {name}. All of these people are here on behalf of Skibbles, Destien, Threadis, and now Kitzy.", objectives = "Take Kitzy to Dornogal to see the Stormrooks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89322] = { id = 89322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brighter Tomorrow", description = "{name}, look at this! All of these people are here to discuss the children's futures. \n\nThey expressed a desire to speak with you as well.", progress = "Have you had a chance to speak with the benefactors?", completion = "{name}, I can't thank you enough. All of these children look like they have bright futures ahead of them, and you played no small part in that. \n\nThanks to you, I also feel as if I understand children a bit better. They are truly wonderful, even if they are a handful at times. \n\n \n\nI know you are very busy, but I do hope we will see you next year!", objectives = "Speak to the recently arrived benefactors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89323] = { id = 89323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasted Lands", description = "Illidan taught us that if we are to fight threats that acknowledge no limits, we must be willing to do the same. With his rage he tamed the power of the fel, and so will I, with the void.\n\nA fragment from this world, touched by the All-Devouring, is held deep in the heart of North Sufaad. With the void essence Leona collected, and this fragment as a vessel, I will yoke the power of the void to my will.\n\nCombining the strength of the illidari and the secrets of the ren'dorei will make me unstoppable.", progress = "Travel to the location of the shard in North Sufaad.", completion = "Its power begs to be released. Can't you hear it?", objectives = "Travel to North Sufaad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89324] = { id = 89324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Piece of Something Greater", description = "Seek out the Relictors. They comb through these wastes like carrion feeders, sifting through proof of their people's weakness in a misguided attempt to find strength.\n\n<Adarus spits contemptuously onto the sand.>\n\nThe only object of real value is here in front of us, and they keep it contained out of fear. I will not make that mistake.\n\nGo, find these Relictors, unburden them of their keys, and return.", progress = "You've proved yourself useful so far, {class}. Continue to do so.", completion = "Retain the fragment for now.\n\nI will need it soon.", objectives = "Retrieve the three keys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89325] = { id = 89325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void Confluence", description = "At last, {name}. With the promise of this fragment's power, and my mastery over the illidari ways, I will be ready to fight the shadowguard and any other threats the void throws at us.\n\nLeona spoke of a cave near Shan'dorah where the void energies suffusing K'aresh converge.\n\nMeet us there, and play a part in my ascension.", completion = "We're nearly prepared. Although I can't help but wonder if Adarus' reach exceeds his grasp.", objectives = "Meet Adarus and Leona at the ritual site inside the cave at the Fracture of Laacuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89326] = { id = 89326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distilled Darkness", description = "Adarus is preparing his mind and body for the ritual.\n\nOur task is to place the fragment at two points within this cavern, which will both align the crystal to the void energy in the area and attract any void entities that reside nearby.\n\nDefeat those entities and their essence will be absorbed into the fragment, empowering it further.", progress = "Move quickly, {name}. Time is of the essence.", completion = "Well done. I'll take it from here.", objectives = "Align the shard of K'aresh with the void energy in the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89327] = { id = 89327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos", description = "This is it, {name}. Place the K'areshi fragment above Adarus, and I will channel the void lure containing Ramon'ta's void essence into the shard.\n\nAdarus is powerful and determined, but we're attempting something both experimental and dangerous.\n\nI'll ask you to be vigilant.", progress = "When you're ready, {name}.", completion = "I didn't have the time or focus to pick a destination for that portal, {name}. He could be anywhere.", objectives = "Assist Adarus and Leona with the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89331] = { id = 89331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame Fortification", description = "Sureki forces are gathering all over Hallowfall and Azj-Kahet--but we're certain they're just distractions. We think the main attack will come from the west.\n\nWhen the time comes we'll need all the help we can get to push them back and defend Mereldar.\n\nCan Flame's Radiance count on your support?", progress = "Be ready, the Sureki could attack at any moment!", completion = "I knew we could count on you!", objectives = "Complete the Nightfall scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89332] = { id = 89332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boot Camp", description = "The Sureki gather across Hallowfall and Azj-Kahet while we prepare for their attack on Mereldar. They want to split our forces, but we cannot ignore their activities elsewhere.\n\nThe Flame's Radiance forces are defending against their incursions in Hallowfall while we run incursions of our own into Azj-Kahet.\n\nRendezvous with the Flame's Radiance in the field and assist their efforts.", completion = "Thank the Sacred Flame for your assistance. The war continues but at least the battle is won.", objectives = "Complete a Radiant Incursion or Sureki Incursion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89334] = { id = 89334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahead of the Issue", description = "I do not know de loa Akil'zon, but she cannot be happy with de gnarldin defilin' de hash'ey shrines and makin' meals of her eagle kin.\n\nWe gotta let dem know dis is a sacred place and dat we will not take kindly to their presence here.\n\nI may not know Akil'zon, but I know de giants. All dey understand is strength--de language of Zul'Aman.\n\nOur strongest message we can send is to take de heads of their fiercest warriors.", progress = "Take their heads. How painful de method is between you and whatever force you worship.", completion = "<Zul'jarra takes one of the heads by the hair and admires your handiwork.>\n\nNow we're talking their language. Now dey know dat de Amani are stronger! \n\nSome may linger, but when we defeat de Twilight's Blade, we will come back for dem.\n\nKeep de heads. I have an idea how dey might be useful later.", objectives = "Collect the heads of Brulagh the Crusher, Cragward Gaahl, and Pulverizer Helthra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89338] = { id = 89338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Plowshares", progress = "The weapons we gather will help reforge Hammerfall's future, {name}.", completion = "Excellent work, {name}. We'll get these reforged into tools, and distribute them to the people.", objectives = "Gather 4 Fallen Longswords and 4 Forgotten Skullcleavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89343] = { id = 89343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Untethered Void", description = "The Reshii Wraps that the Harbinger gave you allow you to briefly transform into energy and fall into Untethered Space. This is a nightmare for all ethereals--a natural result of losing our wraps and radiating away our energy. \n\nWe can control the process by properly attuning with the Phase Conduit, letting us visit this sub-realm and return intact. That is the theory. We have tested it with K'areshi Phase Divers, but not with one of your kind.\n\nAre you willing to risk the journey to Untethered Space?", progress = "Untethered Space is beautiful to visit, but dangerous for those that are trapped there.", completion = "You learn quickly. Good. Untethered Space devours the foolish and unwise.", objectives = "Interact with the Phase Conduit while wearing the Reshii Wraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89344] = { id = 89344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Doesn't See You", description = "Untethered Space is an arcane phenomenon twisted by creatures of the Void that feed on its energy. Should we ethereals damage our wraps or the brokers their suits, our energy cannot remain intact for long. Then, we fall into this layer of reality, possibly never to return.\n\nThe upside of this nightmare is that all the energy that falls out of phase is valuable. Use the Phase Conduit to enter Untethered Space, and fight the observers that scavenge phase energy there.", progress = "Fascinating, isn't it?", completion = "Thank you, {name}. These predators from the Void ambush us and consume the very energy we use to power the eco-domes.", objectives = "Kill Untethered Observers and collect phase energy in Untethered Space on Overlook Zo'Shuul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89345] = { id = 89345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Untethered Horror", description = "Void predators that have recently invaded Untethered Space are a mere annoyance compared to the ancient creatures that traveled here long ago. These primal predators feed on the energies of the remnants of old K'aresh, as well as the unfortunate K'areshi who have fallen into this state of being.\n\nThere is one such creature we call Netherdeath that haunts this rock. We have only been able to drive it away. Perhaps you have the skill to end its reign of terror?", progress = "Have you rid Untethered Space of this predator?", completion = "Netherdeath is no more. Our exploration of Untethered Space can proceed. I knew you were the right person to help us in our endeavors, {name}.\n\nWe would be honored if you would continue to work with us in our exploration.", objectives = "Slay Netherdeath in Untethered Space.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89346] = { id = 89346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Cut of the Spoils" }
quests[89347] = { id = 89347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overcoming the Unknown: Rage-Riddled Drifter" }
quests[89348] = { id = 89348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let There Bee Love", description = "All right. I'll get these bees over to the Oasis and meet you there.", completion = "Let's starting helping the bees get acclimated!", objectives = "Meet Botanist Alaenra at the Oasis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89349] = { id = 89349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame's Radiance Stipend", objectives = "Your exemplary service hasn't gone unnoticed, {name}. I hope this reward serves you well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89351] = { id = 89351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", progress = "Thanks for your business!", completion = "Nice fightin', {name}--now let's see about that rocket ride, eh?", objectives = "Defeat Mug'Zee, Heads of Security within Liberation of Undermine on Normal difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89352] = { id = 89352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", progress = "Thanks for your business!", completion = "Nice fightin', {name}--now let's see about that rocket ride, eh?", objectives = "Defeat Mug'Zee, Heads of Security within Liberation of Undermine on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89353] = { id = 89353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liberation of Undermine: Splitting Pairs", description = "If you're gonna take out the Big G, you're gonna have to bust a few heads - on the very same Ogre, as a matter of fact.\n\nMug'Zee's army of goons litter the Gallagio's shadiest back rooms. If you can secure the Tower of Spades, I'll drop you and your friends off there any time you like.", completion = "Nice fightin', {name}--now let's see about that rocket ride, eh?", objectives = "Defeat Mug'Zee, Heads of Security within Liberation of Undermine on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89354] = { id = 89354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing for Battle", description = "Void creatures have been multiplying throughout Slayer's Rise. Go help clear some out and return to me for a prize. \n\nThere are turrets that are normally used in battle that can be used to make this task easier for you.", completion = "Well done. As promised, here is your reward.", objectives = "Kill 20 Void Creatures in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89377] = { id = 89377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover Hunt" }
quests[89380] = { id = 89380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another World", description = "I represent a group within the Trust tasked with a dangerous but vital job--Phase Diving. I was at Overlook Zo'Shuul when the Harbinger transformed you into energy. It is similar to that, but more profitable.\n\nThe Trust embarks on Phase Dives to help replenish our energy reserves. On K'aresh, energy is power--and now we must compete with the Shadowguard. We desperately need the help of someone like you.\n\nMeet me at Overlook Zo'Shuul if you are interested. We will, of course, compensate you.", completion = "Thank you for accepting our offer, {name}. This is dangerous work that will push you beyond the limits of our reality. But with risk we find profit, and with profit we can change the world.", objectives = "Find Shad'anis at Overlook Zo'Shuul on K'aresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89383] = { id = 89383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Adventurous Hatchling", description = "One of my hatchlings was frightened off when that giant construct marched past the ranch. He bolted right through the fence and into the woods before I could stop him!\n\nHe's small, fast, and probably hiding somewhere nearby. Please find him before something else does, and return him to me.", completion = "Well done, {name}. I'll have that fence reinforced so he can't run off again.", objectives = "Find the missing Hawkstrider Fledgling at Stillwhisper Pond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89384] = { id = 89384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hungry Flock", description = "Some think that raising hawkstriders is an easy task, but it most certainly is not. Hawkstrider appetites tend to be notoriously fussy!\n\nMore often than not they'll turn their beaks up at anything I offer. But this time of year? Frog legs. They love the slimy little things. They can't get enough of them!\n\nThere's a pond just down the hill just swarming with the leggy little morsels. Could you gather some for me, please?", progress = "Have you found any frogs? The hawkstriders are hungry!", completion = "I've been told frog legs taste like a curious blend of fish and poultry. I... think I will leave that fine dining experience to the hawkstriders, however. Thank you for your help!", objectives = "Gather frog legs from the Gloombelly Toads at Stillwhisper Pond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89385] = { id = 89385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Step Into Parenthood", objectives = "Not everyone would go to such lengths for these creatures.\n\nI'd like to give you something special, as thanks for your help. I think you have more than proven you can be entrusted with this.\n\nA hawkstrider egg. Not yet hatched, but there is a little one in there--wiggling, curious, and eager to meet the one who will raise it with love. Take care of it, and it will take good care of you in return.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89386] = { id = 89386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Roost-ed Development", description = "A comfortable hawkstrider is a happy hawkstrider. We don't expect them to stand all day. They need someplace cozy to roost!\n\nThere's a plant called golden sunleaf that sprouts just beyond the ridge. It makes the softest bedding--the hawkstriders love it. Could you gather some for me?", progress = "Did you find the golden sunleaf?", completion = "Oh, they'll have many a happy night's sleep on this! You have my thanks.", objectives = "Collect Golden Sunleaf at Stillwhisper Pond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89388] = { id = 89388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidstorm", description = "Magister Umbric has a plan to infiltrate the Voidstorm and take the fight to the Devouring Host directly.\n\nThis will be no easy task, and he is assembling a small but powerful team to strike at the enemy's heart.", completion = "I hope you are ready for a challenge. This will not be easy.", objectives = "Speak with Magister Umbric in the Sanctum of Light in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[89390] = { id = 89390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame's Radiance Stipend", objectives = "Your service has not gone unnoticed, {name}. I hope this reward serves you well.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
